INSERT INTO "lessons" ("class_id", "title", "summary", "content", "duration_minutes", "is_published", "order")
SELECT c."id", 'Money In, Money Out', $md$What bookkeeping actually is, and the first rule: a separate business bank account.$md$, $md$Bookkeeping is writing down every dollar in (income) and out (expenses) in categories that mean something — and the gap between them, profit, is the number your business lives on. Categorized expenses are tax deductions and forgotten ones are donations to the IRS. First rule: a separate bank account for the business, so every transaction in it is a business transaction by definition.$md$, NULL, true, 1
FROM "classes" c
WHERE c."title" = 'QuickBooks Essentials'
AND NOT EXISTS (SELECT 1 FROM "lessons" l WHERE l."class_id" = c."id" AND l."title" = 'Money In, Money Out')
;

INSERT INTO "lessons" ("class_id", "title", "summary", "content", "duration_minutes", "is_published", "order")
SELECT c."id", 'Setup', $md$QuickBooks Online Simple Start, with your bank account connected.$md$, $md$QuickBooks Online Simple Start is enough to begin. QuickBooks is a paid subscription — check current pricing and start with the free trial (and ask whether a program discount is available).

The one step that matters most: connect your business bank account so transactions import automatically — your job becomes labeling them, not typing them. Check your business name, logo, and invoice numbering (start at 1001).$md$, NULL, true, 2
