INSERT INTO "lessons" ("class_id", "title", "summary", "content", "duration_minutes", "is_published", "order")
SELECT c."id", 'Reconciling', $md$Once a month, prove the books are right.$md$, $md$Weekly categorizing keeps the books current, and monthly reconciling proves they’re *right*. Once a month, match QuickBooks against your actual bank statement (Reconcile, under the gear menu): same starting balance, same ending balance, every transaction accounted for. Fifteen minutes that catches duplicates, missed charges, and bank errors — and means your reports can be trusted.$md$, NULL, true, 6
FROM "classes" c
WHERE c."title" = 'QuickBooks Essentials'
AND NOT EXISTS (SELECT 1 FROM "lessons" l WHERE l."class_id" = c."id" AND l."title" = 'Reconciling')
;

INSERT INTO "lessons" ("class_id", "title", "summary", "content", "duration_minutes", "is_published", "order")
SELECT c."id", 'Taxes', $md$Tax money was never yours. Set it aside on arrival.$md$, $md$Nobody withholds taxes for you now — that’s the money mistake that hurts self-employed people most. The fix is mechanical: every time you get paid, move 25–30% into a separate tax savings account before you touch the rest.

The IRS also expects self-employed people to pay quarterly estimated taxes, not one bill in April — your P&L tells you your profit, and a tax professional (or last year’s return) tells you what to send each quarter. The habit is the lesson: tax money was never yours, so set it aside on arrival.$md$, NULL, true, 7
FROM "classes" c
WHERE c."title" = 'QuickBooks Essentials'
AND NOT EXISTS (SELECT 1 FROM "lessons" l WHERE l."class_id" = c."id" AND l."title" = 'Taxes')
;

INSERT INTO "lessons" ("class_id", "title", "summary", "content", "duration_minutes", "is_published", "order")
SELECT c."id", 'Paying Yourself', $md$Owner’s draw, on a schedule, like a paycheck.$md$, $md$The question every new owner asks. As a sole proprietor or single-owner LLC, you pay yourself with an owner’s draw — transfer money from the business account to your personal account and record it as a draw, not an expense (it doesn’t reduce your profit, and you still owe taxes on profit whether you draw it or not).

Payroll with a real paycheck comes later, mainly if you elect S-corp status — a decision to make with a tax professional. Either way: pay yourself the same amount on the same schedule, like a paycheck, instead of raiding the account when you need money.$md$, NULL, true, 8
FROM "classes" c
WHERE c."title" = 'QuickBooks Essentials'
AND NOT EXISTS (SELECT 1 FROM "lessons" l WHERE l."class_id" = c."id" AND l."title" = 'Paying Yourself')
;

INSERT INTO "lessons" ("class_id", "title", "summary", "content", "duration_minutes", "is_published", "order")
SELECT c."id", 'Reading a P&L', $md$Three questions to ask every month, then one decision.$md$, $md$Income on top, expenses in the middle, profit at the bottom. Monthly, ask three questions:

1. Did I make money?
2. Where did it go (any surprises in the categories)?
3. What changed vs. last month?

Then make one decision based on the answer. That’s running your business on numbers instead of vibes.$md$, NULL, true, 9
FROM "classes" c
WHERE c."title" = 'QuickBooks Essentials'
AND NOT EXISTS (SELECT 1 FROM "lessons" l WHERE l."class_id" = c."id" AND l."title" = 'Reading a P&L')
;

